  1	import { existsSync } from "node:fs";
  2	import { homedir } from "node:os";
  3	import { isAbsolute, join, resolve } from "node:path";
  4	import { readFileSafe } from "./backends/lock.js";
  5	import { AxiError } from "./errors.js";
  6	
  7	/**
  8	 * Backend + path resolution (report §8 config selection).
  9	 *
 10	 * Override order:
 11	 *   --backend / --file flag > TASKS_AXI_* env > project .tasks.toml >
 12	 *   ~/.tasks-axi/config.toml > defaults (markdown, first existing
 13	 *   backlog.md/data/backlog.md, otherwise backlog.md).
 14	 *
 15	 * Markdown remains the default; the ADO backend and future additions stay
 16	 * invisible to the CLI layer behind the Store seam.
 17	 */
 18	
 19	export interface ResolvedConfig {
 20		backend: string;
 21		/** Markdown backlog path (resolved to an absolute path). */
 22		path: string;
 23		/** Optional archive path for pruned tasks (resolved to an absolute path). */
 24		archivePath?: string;
 25		doneKeep: number;
 26		/** Azure DevOps backend settings (`[ado]`), present when configured. */
 27		ado?: AdoConfig;
 28	}
 29	
 30	/** Resolved `[ado]` table (see src/backends/ado.ts for the field map). */
 31	export interface AdoConfig {
 32		org: string;
 33		project: string;
 34		/** Root area path new work items land in, e.g. `Firstmate\\main`. */
 35		area?: string;
 36		workItemType: string;
 37		idField: string;
 38		metaField: string;
 39		followupField: string;
 40		/** ADO state names per tasks-axi state; the first entry is the write value. */
 41		states: Record<AdoState, string[]>;
 42	}
 43	
 44	type AdoState = "queued" | "in_flight" | "done";
 45	
 46	const ADO_DEFAULTS = {
 47		workItemType: "Task",
 48		idField: "Custom.TasksAxiId",
 49		metaField: "Custom.TasksAxiMeta",
 50		followupField: "Custom.TasksAxiPublicFollowup",
 51		states: {
 52			queued: ["New", "To Do", "Proposed"],
 53			in_flight: ["Active", "In Progress", "Doing", "Committed"],
 54			done: ["Closed", "Done", "Resolved", "Removed"],
 55		},
 56	} as const;
 57	
 58	const ADO_REFERENCE_NAME_RE =
 59		/^(?![0-9_])(?=.*\.)[A-Za-z0-9_-](?:[A-Za-z0-9_.-]*[A-Za-z0-9_-])$/;
 60	
 61	const ADO_KEYS = [
 62		"org",
 63		"project",
 64		"area",
 65		"work_item_type",
 66		"id_field",
 67		"meta_field",
 68		"followup_field",
 69		"state_queued",
 70		"state_in_flight",
 71		"state_done",
 72	] as const;
 73	
 74	export interface ConfigOverrides {
 75		backend?: string;
 76		file?: string;
 77		cwd?: string;
 78		home?: string;
 79		env?: NodeJS.ProcessEnv;
 80	}
 81	
 82	interface TomlConfig {
 83		backend?: string;
 84		markdown?: {
 85			path?: string;
 86			archive?: string;
 87			done_keep?: number;
 88		};
 89		ado?: string[];
 90	}
 91	
 92	interface RawTomlConfig {
 93		backend?: string;
 94		markdown?: string[];
 95		ado?: string[];
 96	}
 97	
 98	const DEFAULT_KEEP = 10;
 99	const PATH_CANDIDATES = ["backlog.md", "data/backlog.md"];
100	type ConfigTable = "root" | "markdown" | "ado" | "unsupported";
101	
102	/**
103	 * Minimal TOML reader for the tiny config surface we need: a top-level
104	 * `backend` key, a `[markdown]` table with `path` / `archive` / `done_keep`,
105	 * and an `[ado]` table (org/project/area/fields/state names).
106	 * `archive` points at the file that receives pruned tasks.
107	 * Intentionally not a general TOML parser.
108	 */
109	export function parseConfigToml(src: string): TomlConfig {
110		const raw = scanConfigToml(src);
111		const config: TomlConfig = {};
112		if (raw.backend !== undefined) config.backend = raw.backend;
113		if (raw.markdown) config.markdown = parseMarkdownTable(raw.markdown);
114		if (raw.ado) config.ado = raw.ado;
115		return config;
116	}
117	
118	function scanConfigToml(src: string): RawTomlConfig {
119		const config: RawTomlConfig = {};
120		let table: ConfigTable = "root";
121	
122		for (const rawLine of src.split("\n")) {
123			const line = stripTomlComment(rawLine).trim();
124			if (line === "") continue;
125	
126			const section = line.match(/^\[([^\]]+)\]$/);
127			if (section) {
128				const name = section[1].trim();
129				table =
130					name === "markdown" || name === "ado"
131						? (name as ConfigTable)
132						: "unsupported";
133				continue;
134			}
135	
136			if (table === "markdown") {
137				config.markdown ??= [];
138				config.markdown.push(rawLine);
139				continue;
140			}
141			if (table === "ado") {
142				config.ado ??= [];
143				config.ado.push(rawLine);
144				continue;
145			}
146			if (table === "unsupported") continue;
147	
148			const kv = line.match(/^([A-Za-z0-9_]+)\s*=\s*(.*)$/);
149			if (!kv) {
150				throw new AxiError(
151					"Invalid config line: expected `key = value`",
152					"VALIDATION_ERROR",
153					["Use `key = value` assignments in .tasks.toml"],
154				);
155			}
156			const source = configKeySource(table, kv[1]);
157			if (source) {
158				config.backend = requireTomlString(parseTomlValue(kv[2], source), source);
159			}
160		}
161	
162		return config;
163	}
164	
165	function stripTomlComment(raw: string): string {
166		let quote: '"' | "'" | undefined;
167		for (let i = 0; i < raw.length; i++) {
168			const ch = raw[i];
169			if (quote) {
170				if (ch === quote) quote = undefined;
171				continue;
172			}
173			if (ch === '"' || ch === "'") {
174				quote = ch;
175				continue;
176			}
177			if (ch === "#") return raw.slice(0, i);
178		}
179		return raw;
180	}
181	
182	function configKeySource(table: ConfigTable, key: string): string | undefined {
183		if (table === "root" && key === "backend") return "backend";
184		if (
185			table === "markdown" &&
186			(key === "path" || key === "archive" || key === "done_keep")
187		) {
188			return `markdown.${key}`;
189		}
190		if (table === "ado" && (ADO_KEYS as readonly string[]).includes(key)) {
191			return `ado.${key}`;
192		}
193		return undefined;
194	}
195	
196	function parseMarkdownTable(
197		lines: string[],
198	): NonNullable<TomlConfig["markdown"]> {
199		const values: NonNullable<TomlConfig["markdown"]> = {};
200		for (const rawLine of lines) {
201			const line = stripTomlComment(rawLine).trim();
202			if (line === "") continue;
203			const kv = line.match(/^([A-Za-z0-9_]+)\s*=\s*(.*)$/);
204			if (!kv) {
205				throw new AxiError(
206					"Invalid config line: expected `key = value`",
207					"VALIDATION_ERROR",
208					["Use `key = value` assignments in .tasks.toml"],
209				);
210			}
211			const key = kv[1];
212			const source = configKeySource("markdown", key);
213			if (!source) continue;
214			const value = parseTomlValue(kv[2], source);
215			if (key === "path") values.path = requireTomlString(value, source);
216			if (key === "archive") values.archive = requireTomlString(value, source);
217			if (key === "done_keep") {
218				if (typeof value !== "number") {
219					throw new AxiError(
220						"markdown.done_keep must be an integer",
221						"VALIDATION_ERROR",
222						["Set `[markdown] done_keep = 10` in .tasks.toml"],
223					);
224				}
225				values.done_keep = value;
226			}
227		}
228		return values;
229	}
230	
231	function parseAdoTable(lines: string[]): Record<string, string> {
232		const values: Record<string, string> = {};
233		for (const rawLine of lines) {
234			const line = stripTomlComment(rawLine).trim();
235			if (line === "") continue;
236			const kv = line.match(/^([A-Za-z0-9_]+)\s*=\s*(.*)$/);
237			if (!kv) {
238				throw new AxiError(
239					"Invalid config line: expected `key = value`",
240					"VALIDATION_ERROR",
241					["Use `key = value` assignments in .tasks.toml"],
242				);
243			}
244			const key = kv[1];
245			if (!(ADO_KEYS as readonly string[]).includes(key)) {
246				throw new AxiError(`Unknown ado config key: ${key}`, "VALIDATION_ERROR");
247			}
248			values[key] = kv[2];
249		}
250		return values;
251	}
252	
253	function parseTomlValue(raw: string, source: string): string | number {
254		const trimmed = raw.trim();
255		if (trimmed.startsWith('"') || trimmed.startsWith("'")) {
256			const quote = trimmed[0];
257			if (!trimmed.endsWith(quote) || trimmed.length === 1) {
258				throw new AxiError(
259					`${source} has an unterminated quoted value`,
260					"VALIDATION_ERROR",
261				);
262			}
263			return trimmed.slice(1, -1);
264		}
265		if (/^-?\d+$/.test(trimmed)) return parseInt(trimmed, 10);
266		throw new AxiError(`${source} has an invalid value`, "VALIDATION_ERROR");
267	}
268	
269	function requireTomlString(value: string | number, source: string): string {
270		if (typeof value === "string") return value;
271		throw new AxiError(`${source} must be a quoted string`, "VALIDATION_ERROR");
272	}
