118	function scanConfigToml(src: string): RawTomlConfig {
119		const config: RawTomlConfig = {};
120		let table: ConfigTable = "root";
121	
122		for (const rawLine of src.split("\n")) {
123			const line = stripTomlComment(rawLine).trim();
124			if (line === "") continue;
125	
126			const section = line.match(/^\[([^\]]+)\]$/);
127			if (section) {
