164	/** Strip the global --backend/--file flags and run the handler on the rest. */
165	function withContext(handler: CommandFn): CommandFn {
166		return (args) => {
167			const { backend, file, stripped, suggestionGlobals } =
168				parseGlobalFlags(args);
169			const ctx = resolveTasksContext(
170				{
171					...(backend !== undefined ? { backend } : {}),
172					...(file !== undefined ? { file } : {}),
173				},
174				suggestionGlobals,
175			);
176			return handler(stripped, ctx);
177		};
178	}
179	
180	function parseGlobalFlags(args: string[]): {
181		backend?: string;
182		file?: string;
183		stripped: string[];
184		suggestionGlobals?: SuggestionGlobals;
185	} {
186		const stripped: string[] = [];
187		let backend: string | undefined;
188		let file: string | undefined;
189	
190		for (let i = 0; i < args.length; i++) {
191			const arg = args[i];
192			if (arg === "--backend") {
193				const value = requireFlagValue(args, i, "--backend");
194				backend = requireNonEmptyGlobalFlagValue("--backend", value);
195				i++;
196				continue;
197			}
198			if (arg.startsWith("--backend=")) {
199				backend = requireNonEmptyGlobalFlagValue(
200					"--backend",
201					arg.slice("--backend=".length),
202				);
203				continue;
204			}
205			if (arg === "--file") {
206				const value = requireFlagValue(args, i, "--file");
207				file = requireNonEmptyGlobalFlagValue("--file", value);
208				i++;
209				continue;
210			}
211			if (arg.startsWith("--file=")) {
212				file = requireNonEmptyGlobalFlagValue(
213					"--file",
214					arg.slice("--file=".length),
215				);
216				continue;
217			}
218			stripped.push(arg);
219		}
220	
221		return {
222			...(backend ? { backend } : {}),
223			...(file ? { file } : {}),
224			stripped,
225			...(backend !== undefined || file !== undefined
226				? {
227						suggestionGlobals: {
228							...(backend !== undefined ? { backend } : {}),
229							...(file !== undefined ? { file } : {}),
230						},
231					}
232				: {}),
233		};
234	}
235	
236	function requireNonEmptyGlobalFlagValue(flag: string, value: string): string {
237		return requireNonEmptySingleLineFlagValue(flag, value) ?? value;
238	}

