153	export async function doneCommand(
154	  rawArgs: string[],
155	  context?: TasksContext,
156	): Promise<string> {
157	  const { store, config } = requireCtx(context);
158	  const args = [...rawArgs];
159	
160	  const json = takeBoolFlag(args, "--json");
161	  const pr = requireNonEmptyFlagValue("--pr", takeFlag(args, "--pr"));
162	  const report = requireNonEmptyFlagValue(
163	    "--report",
164	    takeFlag(args, "--report"),
165	  );
166	  const note = requireNonEmptyFlagValue("--note", takeFlag(args, "--note"));
167	  const keepRaw = takeFlag(args, "--keep");
168	  const noPrune = takeBoolFlag(args, "--no-prune");
169	  const positionals = requirePositionals(args, 1, 1, DONE_HELP.split("\n")[0]);
170	  const id = requireId(positionals[0], "id");
171	  const keep = parseNonNegativeIntegerFlag("--keep", keepRaw, config.doneKeep);
172	
173	  const current = await store.get(id);
174	  if (!current) throw notFound(id, { globals: context?.suggestionGlobals });
175	
176	  const opts: { pr?: string; report?: string; note?: string } = {};
177	  if (pr !== undefined) opts.pr = pr;
178	  if (report !== undefined) opts.report = report;
179	  if (note !== undefined) opts.note = note;
180	
181	  if (current.state === "done") {
182	    const patch = doneMetadataPatch(pr, report, note);
183	    const hasPatch = Object.keys(patch).length > 0;
184	    let task = current;
185	    let changed = false;
186	    if (hasPatch) {
187	      const result = await store.update(id, patch);
188	      task = result.task;
189	      changed = result.changed.length > 0;
190	    }
191	    const pruned = await pruneDone(store, keep, noPrune);
192	    const all = (await store.list({})).items;
193	    return renderMutation({
194	      json,
195	      confirm: `done ${id} already -> ${stateLabel(task.state)}${doneExtras(pr, report)}${prunedNote(pruned)}`,
196	      already: true,
197	      jsonPayload: {
198	        ok: true,
199	        action: "done",
200	        already: true,
201	        pruned,
202	        task: taskToJson(task, all),
203	      },
204	      ...(changed
205	        ? { detail: renderTaskDetail(task, all, false, showFullTextHint(task)) }
206	        : {}),
207	      suggestions: getSuggestions({
208	        action: "done",
209	        id,
210	        state: task.state,
211	        globals: context?.suggestionGlobals,
212	      }),
213	    });
214	  }
215	
216	  const task = await store.transition(id, "done", opts);
217	  const pruned = await pruneDone(store, keep, noPrune);
218	  const all = (await store.list({})).items;
219	
220	  return renderMutation({
221	    json,
222	    confirm: `done ${id} -> ${stateLabel(task.state)}${doneExtras(pr, report)}${prunedNote(pruned)}`,
223	    jsonPayload: {
224	      ok: true,
225	      action: "done",
226	      pruned,
227	      task: taskToJson(task, all),
228	    },
229	    suggestions: getSuggestions({
230	      action: "done",
231	      id,
232	      state: task.state,
233	      globals: context?.suggestionGlobals,
234	    }),
235	  });
