242	): string {
243	  const parts: string[] = [];
244	  if (pr !== undefined) parts.push(`pr ${pr}`);
245	  if (report !== undefined) parts.push(`report ${report}`);
246	  return parts.length > 0 ? ` (${parts.join(", ")})` : "";
247	}
