 13	/**
 14	 * The resolved CLI context: the active backend Store plus the config that
 15	 * selected it. The command layer only ever talks to `Store`, so swapping in
 16	 * sqlite/remote backends (P2/P3) never touches arg parsing or rendering.
 17	 */
 18	export interface TasksContext {
 19	  store: Store;
 20	  config: ResolvedConfig;
 21	  suggestionGlobals?: SuggestionGlobals;
 22	}
 23	
 24	export function resolveTasksContext(
 25	  overrides: ConfigOverrides = {},
 26	  suggestionGlobals?: SuggestionGlobals,
 27	): TasksContext {
 28	  const env = overrides.env ?? process.env;
 29	  const config = resolveConfig({ ...overrides, env });
 30	
 31	  if (config.backend !== "markdown" && config.backend !== "ado") {
 32	    throw new AxiError(
 33	      `Unsupported backend "${config.backend}" — tasks-axi ships the markdown and ado backends`,
 34	      "UNSUPPORTED",
 35	      ['Set `backend = "markdown"` in .tasks.toml, or omit --backend'],
 36	    );
 37	  }
 38	
 39	  return {
 40	    store:
 41	      config.backend === "ado" ? adoStore(config, env) : markdownStore(config),
 42	    config,
 43	    ...(suggestionGlobals ? { suggestionGlobals } : {}),
 44	  };
 45	}
 46	
 47	function markdownStore(config: ResolvedConfig): Store {
 48	  return new MarkdownStore({
 49	    path: config.path,
 50	    ...(config.archivePath ? { archivePath: config.archivePath } : {}),
 51	  });
 52	}
 53	
 54	function adoStore(config: ResolvedConfig, env: NodeJS.ProcessEnv): Store {
 55	  const ado = config.ado;
 56	  if (!ado) {
 57	    throw new AxiError(
 58	      "The ado backend needs an `[ado]` config table",
 59	      "VALIDATION_ERROR",
 60	      ['Set `[ado] org = "contoso"` and `project = "Internal"` in .tasks.toml'],
 61	    );
 62	  }
 63	  return new AdoStore({
 64	    client: new AdoRestClient({ org: ado.org, project: ado.project, env }),
 65	    project: ado.project,
 66	    ...(ado.area ? { area: ado.area } : {}),
 67	    workItemType: ado.workItemType,
 68	    idField: ado.idField,
 69	    metaField: ado.metaField,
 70	    followupField: ado.followupField,
 71	    states: ado.states,
 72	  });
 73	}
