 75	/** Narrow an optional context to a present one (the resolver always sets it). */
 76	export function requireCtx(ctx: TasksContext | undefined): TasksContext {
 77	  if (!ctx) {
 78	    throw new AxiError("backlog context was not resolved", "UNKNOWN");
 79	  }
 80	  return ctx;
 81	}

