 12	/**
 13	 * The markdown grammar: pure parse / render with no I/O.
 14	 *
 15	 * Strategy for the byte-exact round-trip (report §2.4, decision D1):
 16	 *  - Every entry keeps its exact original source lines (`raw`). An unmodified
 17	 *    task and any free-form line is emitted verbatim, so `render(parse(src))`
 18	 *    equals `src` byte-for-byte on a file nobody has mutated.
 19	 *  - When a task is mutated, it is marked `dirty` and re-rendered from its
 20	 *    structured fields into a canonical, re-parseable form. Untouched entries
 21	 *    stay verbatim, so a targeted task edit never disturbs the rest of the file.
 22	 *  - `render()` (the verb) marks every task dirty to normalize the whole file.
 23	 *
 24	 * Free-form (no-id) lines are preserved verbatim and never operated on by id
 25	 * (decision D7).
 26	 */
 27	
 28	// ---------------------------------------------------------------------------
 29	// Document model
 30	// ---------------------------------------------------------------------------
 31	
 32	export interface TaskEntry {
 33	  kind: "task";
 34	  task: Task;
 35	  /** Exact original source lines (bullet + indented continuations). */
 36	  raw: string[];
 37	  /** When true, render from `task`; otherwise emit `raw` verbatim. */
 38	  dirty: boolean;
 39	}
 40	
 41	export interface RawEntry {
 42	  kind: "raw";
 43	  lines: string[];
 44	}
 45	
 46	export type Entry = TaskEntry | RawEntry;
 47	
 48	export interface Section {
 49	  /** Exact header line, e.g. "## In flight" or "## Done (10 most recent)". */
 50	  headerLine: string;
 51	  /** Recognized task-bearing state, or undefined for a passthrough section. */
 52	  state?: State;
