 67	const ID_CHARS = "[A-Za-z0-9][A-Za-z0-9._-]*";
 68	const IN_FLIGHT_RE = new RegExp(`^- \\*\\*(${ID_CHARS})\\*\\* - (.*)$`);
 69	const QUEUED_RE = new RegExp(`^- \\[ \\] (${ID_CHARS}) - (.*)$`);
 70	const DONE_RE = new RegExp(`^- \\[x\\] (${ID_CHARS}) - (.*)$`);
 71	
 72	/** Validate a caller-supplied id round-trips through the markdown grammar. */
 73	export const ID_RE = new RegExp(`^${ID_CHARS}$`);
 74	
 75	function semanticLine(line: string): string {
 76	  return line.endsWith("\r") ? line.slice(0, -1) : line;
 77	}
 78	
 79	function matchOne(
 80	  line: string,
 81	  re: RegExp,
 82	): { id: string; rest: string } | null {
 83	  const m = line.match(re);
 84	  return m ? { id: m[1], rest: m[2] } : null;
 85	}
 86	
 87	function matchTaskBullet(
 88	  line: string,
 89	  state: State,
 90	): { id: string; rest: string } | null {
 91	  if (state === "done") return matchOne(line, DONE_RE);
 92	  if (state === "queued") return matchOne(line, QUEUED_RE);
 93	  // In flight: firstmate writes the GitHub-style `- [ ] <id>` checkbox (the same
 94	  // bullet as Queued; the section header is what distinguishes the state), while
 95	  // older tasks-axi output used `- **<id>**`. Recognize both so a file either
 96	  // tool wrote is readable by the other.
 97	  return matchOne(line, IN_FLIGHT_RE) ?? matchOne(line, QUEUED_RE);
 98	}
