100	// ---------------------------------------------------------------------------
101	// Inline tag extraction (canonical fields) + link/kind derivation
102	// ---------------------------------------------------------------------------
103	
104	// Canonical tags are recognized only in the TRAILING tag-region of a line, so
105	// a mid-sentence parenthetical (e.g. "report.md (reported 2026-06-22): ...") is
106	// left untouched in the prose and never duplicated or relocated on re-render.
107	const DATE = "\\d{4}-\\d{2}-\\d{2}";
108	// A trailing dependency edge, optionally carrying firstmate's free-text reason
109	// after a ` - ` delimiter, e.g. `blocked-by: fix-login-k3 - waits on the login
110	// refactor`. The id stops at the first space, and the reason stops before the
111	// next trailing dependency marker.
112	const DEP_MARKER = "(?:blocked-by|parent|discovered-from)";
113	const TAIL_DEP = new RegExp(
114	  `\\s*(${DEP_MARKER}):\\s*(${ID_CHARS})(?:\\s+-\\s+((?:(?!\\s+${DEP_MARKER}:\\s).)+?))?\\s*$`,
115	);
116	const TAIL_REPO = /\s*\((?:[^()]*\+\s*)?repo:\s*([^)]+)\)\s*$/;
117	const TAIL_KIND = /\s*\(kind:\s*([^)]+)\)\s*$/;
118	const TAIL_PRIORITY = /\s*\(priority:\s*([0-4])\)\s*$/;
119	const TAIL_SINCE = new RegExp(`\\s*\\(since\\s+(${DATE})\\)\\s*$`);
120	const TAIL_CLOSED = new RegExp(
121	  `\\s*\\((?:merged|reported|done|closed)\\s+(${DATE})\\)\\s*$`,
122	);
123	const TAIL_HOLD = /\s*\(hold:\s*([^()]+)\)\s*$/;
124	const TAIL_HOLD_KIND = new RegExp(
125	  `\\s*\\(hold-kind:\\s*(${HOLD_KINDS.join("|")})\\)\\s*$`,
126	);
127	const TAIL_HOLD_UNTIL = new RegExp(`\\s*\\(hold-until:\\s*(${DATE})\\)\\s*$`);
128	
129	const REPORT_LINK = /\bdata\/\S+?\/report\.md\b/g;
130	const GENERIC_URL = /https?:\/\/\S+/g;
131	
132	const LEADING_KIND: Array<[RegExp, string]> = [
133	  [/^PERSISTENT SECONDMATE\b/, "secondmate"],
134	  [/^SHIP\b/, "ship"],
135	  [/^SCOUT\b/, "scout"],
136	  [/^DOCS-ONLY\b/, "docs"],
