139	/** The kind implied by a leading prose word (legacy display), or undefined. */
140	export function leadingKind(title: string): string | undefined {
141	  for (const [re, kind] of LEADING_KIND) {
142	    if (re.test(title)) return kind;
143	  }
144	  return undefined;
145	}
146	
147	function titleHasLeadingKind(title: string, kind: string): boolean {
148	  return leadingKind(title) === kind;
