155	/** Derive typed links by scanning prose (links live in the prose, not as tags). */
156	export function deriveLinks(text: string): TaskLink[] {
157	  const links: TaskLink[] = [];
158	  const seen = new Set<string>();
159	  const add = (kind: TaskLink["kind"], raw: string) => {
160	    const url = trimUrl(raw);
161	    if (seen.has(url)) return;
162	    seen.add(url);
163	    links.push({ kind, url });
164	  };
165	  for (const m of text.matchAll(GENERIC_URL)) {
166	    if (isPrUrl(trimUrl(m[0]))) add("pr", m[0]);
167	  }
168	  for (const m of text.matchAll(REPORT_LINK)) add("report", m[0]);
169	  for (const m of text.matchAll(GENERIC_URL)) {
170	    if (!isPrUrl(trimUrl(m[0]))) add("doc", m[0]);
171	  }
172	  return links;
173	}
