175	export function normalizeTypedLink(link: TaskLink): TaskLink {
176	  if (/\r|\n/.test(link.url)) {
177	    throw new AxiError("Task link must be a single line", "VALIDATION_ERROR");
178	  }
179	  const normalized = link.url.trim();
180	  if (normalized === "") {
181	    throw new AxiError("Task link must not be empty", "VALIDATION_ERROR");
182	  }
183	  const url = link.kind === "pr" ? link.url : normalized;
184	  if (
185	    !deriveLinks(url).some(
186	      (candidate) => candidate.kind === link.kind && candidate.url === url,
187	    )
188	  ) {
189	    const expected =
190	      link.kind === "pr"
191	        ? PR_URL_EXPECTED
192	        : link.kind === "report"
193	          ? "a data/<id>/report.md path"
194	          : "an http(s) URL";
195	    throw new AxiError(
196	      `Task ${link.kind} link must be ${expected}`,
197	      "VALIDATION_ERROR",
198	    );
199	  }
200	  return { kind: link.kind, url };
201	}
202	
203	export function normalizeTypedLinks(links: TaskLink[]): TaskLink[] {
204	  const normalized: TaskLink[] = [];
205	  const seen = new Set<string>();
206	  for (const link of links) {
207	    const next = normalizeTypedLink(link);
208	    if (seen.has(next.url)) continue;
209	    seen.add(next.url);
210	    normalized.push(next);
211	  }
212	  return normalized;
213	}
