100	function normalizeTitle(title: string): string {
101	  if (/[\r\n]/.test(title)) {
102	    throw new AxiError("Task title must be a single line", "VALIDATION_ERROR");
103	  }
104	  const trimmed = title.trim();
105	  if (trimmed === "") {
106	    throw new AxiError("Task title must not be empty", "VALIDATION_ERROR");
107	  }
108	  if (extractTags(trimmed).title !== trimmed) {
109	    throw new AxiError(
110	      "Task title must not end with canonical task tags",
111	      "VALIDATION_ERROR",
112	    );
113	  }
114	  return trimmed;
115	}
