117	function normalizeTagValue(
118	  value: string | undefined,
119	  field: "kind" | "repo",
120	): string | undefined {
121	  if (value === undefined) return undefined;
122	  if (/[()\r\n]/.test(value)) {
123	    throw new AxiError(
124	      `Task ${field} must be a single line without parentheses`,
125	      "VALIDATION_ERROR",
126	    );
127	  }
128	  const trimmed = value.trim();
