146	    throw new AxiError(
147	      "Task hold reason must be a single line without parentheses",
148	      "VALIDATION_ERROR",
149	    );
150	  }
151	  const reason = hold.reason.trim();
152	  if (reason === "") {
153	    throw new AxiError(
154	      "Task hold reason must not be empty",
155	      "VALIDATION_ERROR",
156	    );
157	  }
158	  const normalized: Hold = { reason };
159	  if (hold.kind !== undefined) {
160	    if (!(HOLD_KINDS as readonly string[]).includes(hold.kind)) {
161	      throw new AxiError(
162	        `Task hold kind must be one of ${HOLD_KINDS.join(", ")}`,
163	        "VALIDATION_ERROR",
164	      );
165	    }
166	    normalized.kind = hold.kind;
167	  }
168	  if (hold.until !== undefined) {
169	    normalized.until = normalizeDate(hold.until, "hold-until date");
170	  }
171	  return normalized;
172	}
