181	function normalizeDepReason(reason: string | undefined): string | undefined {
182	  if (reason === undefined) return undefined;
183	  if (/[\r\n]/.test(reason)) {
184	    throw new AxiError(
185	      "Task dependency reason must be a single line",
186	      "VALIDATION_ERROR",
187	    );
188	  }
