199	function normalizeDep(ownerId: string, dep: Dep): Dep {
200	  const reason = normalizeDepReason(dep.reason);
201	  const checked: Dep = { ...dep, id: validateDependencyId(dep.id) };
202	  if (reason === undefined) {
203	    delete checked.reason;
204	  } else {
205	    checked.reason = reason;
206	  }
207	  if (checked.id === ownerId) {
208	    throw new AxiError("A task cannot block itself", "VALIDATION_ERROR");
209	  }
210	  return checked;
