237	  right: Record<string, unknown> | undefined,
238	): boolean {
239	  const leftKeys = Object.keys(left ?? {});
240	  const rightKeys = Object.keys(right ?? {});
241	  return (
242	    leftKeys.length === rightKeys.length &&
243	    leftKeys.every((key) => Object.is(left?.[key], right?.[key]))
244	  );
