248	  const input: TaskInput = {
249	    id: task.id,
250	    title: task.title,
251	    state: task.state,
252	    deps: task.deps.map((dep) => ({ ...dep })),
253	    links: task.links.map((link) => ({ ...link })),
254	  };
255	  if (task.kind) input.kind = task.kind;
256	  if (task.repo) input.repo = task.repo;
257	  if (task.body) input.body = task.body;
258	  if (task.hold) input.hold = { ...task.hold };
259	  if (task.priority !== undefined) input.priority = task.priority;
260	  input.created = task.created ?? null;
261	  if (task.closed) input.closed = task.closed;
262	  if (task.public_followup) {
263	    input.public_followup = clonePublicFollowup(task.public_followup);
264	  }
265	  if (task.meta) input.meta = { ...task.meta };
266	  return input;
