   489	export function resolveConfig(overrides: ConfigOverrides = {}): ResolvedConfig {
   490		const env = overrides.env ?? process.env;
   491		const cwd = overrides.cwd ?? process.cwd();
   492		const home = overrides.home ?? homedir();
   493	
   494		const homeToml = loadToml(join(home, ".tasks-axi", "config.toml"));
   495		const projectToml = loadToml(resolve(cwd, ".tasks.toml"));
   496		const backend =
   497			overrides.backend ??
   498			env.TASKS_AXI_BACKEND ??
   499			projectToml.backend ??
   500			homeToml.backend ??
   501			"markdown";
   502		const config: ResolvedConfig = {
   503			backend,
   504			path: resolveMarkdownPath(undefined, undefined, cwd),
   505			doneKeep: DEFAULT_KEEP,
   506		};
   507	
   508		if (backend === "ado") {
   509			const ado = resolveAdo(
   510				{
   511					...parseAdoTable(homeToml.ado ?? []),
   512					...parseAdoTable(projectToml.ado ?? []),
   513				},
   514				env,
   515			);
   516			if (ado) config.ado = ado;
   517			return config;
   518		}
   519		if (backend !== "markdown") return config;
   520	
   521		const homeMarkdown = parseMarkdownTable(homeToml.markdown ?? []);
   522		const projectMarkdown = parseMarkdownTable(projectToml.markdown ?? []);
   523		const markdown = { ...homeMarkdown, ...projectMarkdown };
   524		const explicitPath =
   525			overrides.file !== undefined
   526				? validatePathValue(overrides.file, "--file")
   527				: env.TASKS_AXI_FILE !== undefined
   528					? validatePathValue(env.TASKS_AXI_FILE, "TASKS_AXI_FILE")
   529					: undefined;
   530		const tomlPath =
   531			explicitPath === undefined
   532				? validatePathValue(markdown.path, "markdown.path")
   533				: undefined;
   534		config.path = resolveMarkdownPath(explicitPath, tomlPath, cwd);
   535		const archive = validatePathValue(markdown.archive, "markdown.archive");
   536		config.doneKeep = validateDoneKeep(markdown.done_keep ?? DEFAULT_KEEP);
   537		if (archive) {
   538			config.archivePath = isAbsolute(archive) ? archive : resolve(cwd, archive);
   539		}
   540		return config;
   541	}
