 36	interface TomlConfig {
 37	  backend?: string;
 38	  markdown?: {
 39	    path?: string;
 40	    archive?: string;
 41	    done_keep?: number;
 42	  };
 43	}
 44	
 45	const DEFAULT_KEEP = 10;
 46	const PATH_CANDIDATES = ["backlog.md", "data/backlog.md"];
 47	type ConfigTable = "root" | "markdown" | "unsupported";
 48	
 49	/**
 50	 * Minimal TOML reader for the tiny config surface we need: a top-level
 51	 * `backend` key and a `[markdown]` table with `path` / `archive` / `done_keep`.
 52	 * `archive` points at the file that receives pruned tasks.
 53	 * Intentionally not a general TOML parser.
 54	 */
 55	export function parseConfigToml(src: string): TomlConfig {
 56	  const config: TomlConfig = {};
 57	  let table: ConfigTable = "root";
 58	
 59	  for (const rawLine of src.split("\n")) {
 60	    const line = stripTomlComment(rawLine).trim();
 61	    if (line === "") continue;
 62	
 63	    const section = line.match(/^\[([^\]]+)\]$/);
 64	    if (section) {
 65	      table = section[1].trim() === "markdown" ? "markdown" : "unsupported";
 66	      continue;
 67	    }
 68	
 69	    if (table === "unsupported") continue;
 70	
 71	    const kv = line.match(/^([A-Za-z0-9_]+)\s*=\s*(.*)$/);
 72	    if (!kv) {
 73	      throw new AxiError(
 74	        "Invalid config line: expected `key = value`",
 75	        "VALIDATION_ERROR",
 76	        ["Use `key = value` assignments in .tasks.toml"],
 77	      );
 78	    }
 79	    const key = kv[1];
 80	    const source = configKeySource(table, key);
 81	    if (!source) continue;
 82	    const value = parseTomlValue(kv[2], source);
 83	
 84	    if (table === "root") {
 85	      config.backend = requireTomlString(value, source);
 86	      continue;
 87	    }
 88	    config.markdown ??= {};
 89	    if (key === "path") config.markdown.path = requireTomlString(value, source);
 90	    if (key === "archive")
 91	      config.markdown.archive = requireTomlString(value, source);
 92	    if (key === "done_keep") {
 93	      if (typeof value !== "number") {
 94	        throw new AxiError(
 95	          "markdown.done_keep must be an integer",
 96	          "VALIDATION_ERROR",
 97	          ["Set `[markdown] done_keep = 10` in .tasks.toml"],
 98	        );
 99	      }
100	      config.markdown.done_keep = value;
101	    }
102	  }
103	
104	  return config;
105	}
