107	function stripTomlComment(raw: string): string {
108	  let quote: '"' | "'" | undefined;
109	  for (let i = 0; i < raw.length; i++) {
110	    const ch = raw[i];
111	    if (quote) {
112	      if (ch === quote) quote = undefined;
113	      continue;
114	    }
115	    if (ch === '"' || ch === "'") {
116	      quote = ch;
117	      continue;
118	    }
119	    if (ch === "#") return raw.slice(0, i);
120	  }
121	  return raw;
122	}
123	
124	function configKeySource(
125	  table: ConfigTable,
126	  key: string,
127	): string | undefined {
128	  if (table === "root" && key === "backend") return "backend";
129	  if (
130	    table === "markdown" &&
131	    (key === "path" || key === "archive" || key === "done_keep")
132	  ) {
133	    return `markdown.${key}`;
134	  }
135	  return undefined;
136	}
137	
138	function parseTomlValue(raw: string, source: string): string | number {
139	  const trimmed = raw.trim();
140	  if (trimmed.startsWith('"') || trimmed.startsWith("'")) {
141	    const quote = trimmed[0];
142	    if (!trimmed.endsWith(quote) || trimmed.length === 1) {
143	      throw new AxiError(
144	        `${source} has an unterminated quoted value`,
145	        "VALIDATION_ERROR",
146	      );
147	    }
148	    return trimmed.slice(1, -1);
149	  }
150	  if (/^-?\d+$/.test(trimmed)) return parseInt(trimmed, 10);
151	  throw new AxiError(`${source} has an invalid value`, "VALIDATION_ERROR");
152	}
153	
154	function requireTomlString(value: string | number, source: string): string {
155	  if (typeof value === "string") return value;
156	  throw new AxiError(`${source} must be a quoted string`, "VALIDATION_ERROR");
157	}
158	
159	function loadToml(path: string): TomlConfig {
160	  const src = readFileSafe(path);
161	  return src ? parseConfigToml(src) : {};
162	}
163	
164	function resolveMarkdownPath(
165	  explicit: string | undefined,
166	  tomlPath: string | undefined,
167	  cwd: string,
168	): string {
169	  const chosen = explicit ?? tomlPath;
170	  if (chosen) return isAbsolute(chosen) ? chosen : resolve(cwd, chosen);
171	
172	  for (const candidate of PATH_CANDIDATES) {
173	    const full = resolve(cwd, candidate);
174	    if (existsSync(full)) return full;
175	  }
176	  return resolve(cwd, PATH_CANDIDATES[0]);
177	}
178	
179	function validatePathValue(
180	  value: string | undefined,
181	  source: string,
182	): string | undefined {
183	  if (value === undefined) return undefined;
184	  if (value.trim() === "") {
185	    throw new AxiError(`${source} must not be empty`, "VALIDATION_ERROR", [
186	      "Set it to a backlog path or remove the empty override",
187	    ]);
188	  }
189	  return value;
190	}
191	
192	function validateDoneKeep(value: number): number {
193	  if (!Number.isSafeInteger(value) || value < 0) {
194	    throw new AxiError(
195	      "markdown.done_keep must be a non-negative integer",
196	      "VALIDATION_ERROR",
197	      ["Set `[markdown] done_keep = 10` in .tasks.toml"],
198	    );
199	  }
200	  return value;
201	}
