203	export function resolveConfig(overrides: ConfigOverrides = {}): ResolvedConfig {
204	  const env = overrides.env ?? process.env;
205	  const cwd = overrides.cwd ?? process.cwd();
206	  const home = overrides.home ?? homedir();
207	
208	  const homeToml = loadToml(join(home, ".tasks-axi", "config.toml"));
209	  const projectToml = loadToml(resolve(cwd, ".tasks.toml"));
210	
211	  const explicitPath =
212	    overrides.file !== undefined
213	      ? validatePathValue(overrides.file, "--file")
214	      : env.TASKS_AXI_FILE !== undefined
215	        ? validatePathValue(env.TASKS_AXI_FILE, "TASKS_AXI_FILE")
216	        : undefined;
217	  const tomlPath =
218	    explicitPath !== undefined
219	      ? undefined
220	      : projectToml.markdown?.path !== undefined
221	        ? validatePathValue(projectToml.markdown.path, "markdown.path")
222	        : validatePathValue(homeToml.markdown?.path, "markdown.path");
223	
224	  const backend =
225	    overrides.backend ??
226	    env.TASKS_AXI_BACKEND ??
227	    projectToml.backend ??
228	    homeToml.backend ??
229	    "markdown";
230	
231	  const path = resolveMarkdownPath(explicitPath, tomlPath, cwd);
232	
233	  const archive =
234	    projectToml.markdown?.archive !== undefined
235	      ? validatePathValue(projectToml.markdown.archive, "markdown.archive")
236	      : validatePathValue(homeToml.markdown?.archive, "markdown.archive");
