554	export class AdoStore implements Store {
555		private readonly client: AdoClient;
556		private readonly project: string;
557		private readonly area?: string;
558		private readonly workItemType: string;
559		private readonly idField: string;
560		private readonly metaField: string;
561		private readonly followupField: string;
562		private readonly states: Record<State, string[]>;
563		private readonly now: () => string;
564	
565		constructor(options: AdoStoreOptions) {
566			this.client = options.client;
567			this.project = options.project;
568			if (options.area) this.area = options.area;
569			this.workItemType = options.workItemType;
570			this.idField = options.idField;
571			this.metaField = options.metaField;
572			this.followupField = options.followupField;
573			this.states = options.states;
574			this.now = options.now ?? today;
575		}
576	
577		capabilities(): Capabilities {
578			return {
579				backend: "ado",
580				deps: true,
581				// No hard prune and no canonical re-render: ADO owns its own storage.
582				prune: false,
583				comments: false,
584				fullTextSearch: false,
585				realtimeSync: false,
586				customStates: false,
587				serverMintsIds: false,
588				publicFollowups: true,
589				fileMoves: false,
590			};
591		}
592	
593		// ---------------------------------------------------------------------
594		// State mapping
595		// ---------------------------------------------------------------------
596	
597		private adoState(state: State): string {
598			return this.states[state][0];
599		}
600	
601		private toState(adoState: string): State {
602			const normalized = adoState.toLowerCase();
603			for (const state of ["queued", "in_flight", "done"] as State[]) {
604				if (
605					this.states[state].some((name) => name.toLowerCase() === normalized)
606				) {
607					return state;
608				}
609			}
610			return validation(
611				`Azure DevOps state "${adoState}" is not mapped to a tasks-axi state`,
612				[
613					"Add it to `[ado] state_queued` / `state_in_flight` / `state_done` in .tasks.toml",
614				],
615			);
616		}
617	
618		// ---------------------------------------------------------------------
619		// Read
620		// ---------------------------------------------------------------------
621	
622		private wiql(where: string[], area = this.area): string {
623			const clauses = [
624				`[System.TeamProject] = '${sq(this.project)}'`,
625				`[System.WorkItemType] = '${sq(this.workItemType)}'`,
626				`[${this.idField}] <> ''`,
627				...(area ? [`[System.AreaPath] UNDER '${sq(area)}'`] : []),
628				...where,
629			];
630			return `SELECT [System.Id] FROM WorkItems WHERE ${clauses.join(" AND ")}`;

