 12	
 13	export const PRUNE_HELP = `usage: tasks-axi prune [--keep <n>] [--state done]
 14	Trim a section to the N most recent tasks, archiving the rest (never deletes).
 15	flags:
 16	  --keep <n>   tasks to retain (default from config, usually 10)
 17	  --state <queued|in_flight|done>   section to prune (default done)
 18	  --json   print the result as a JSON object
 19	examples:
 20	  tasks-axi prune --keep 10`;
 21	
 22	export const RENDER_HELP = `usage: tasks-axi render
 23	Normalize the backlog file: rewrite every id'd task in canonical form.
 24	Free-form lines are left untouched.
 25	flags:
 26	  --json   print the result as a JSON object`;
 27	
 28	export async function pruneCommand(
 29	  rawArgs: string[],
 30	  context?: TasksContext,
 31	): Promise<string> {
 32	  const { store, config } = requireCtx(context);
 33	  const args = [...rawArgs];
 34	
 35	  const json = takeBoolFlag(args, "--json");
 36	  if (!store.prune) {
 37	    throw unsupported("prune", store.capabilities().backend);
 38	  }
 39	
 40	  const keepRaw = takeFlag(args, "--keep");
 41	  const keep = parseNonNegativeIntegerFlag("--keep", keepRaw, config.doneKeep);
 42	  const state = parseStateFlag("--state", takeFlag(args, "--state"), "done");
 43	  requirePositionals(args, 0, 0, PRUNE_HELP.split("\n")[0]);
 44	
 45	  const result = await store.prune({ state, keep, archive: true });
 46	
 47	  return renderMutation({
 48	    json,
 49	    confirm: `prune ${state} -> archived ${result.archived} (kept ${keep})`,
 50	    jsonPayload: {
 51	      ok: true,
 52	      action: "prune",
 53	      state,
 54	      kept: keep,
 55	      archived: result.archived,
 56	      ids: result.ids,
 57	    },
 58	    suggestions: getSuggestions({
 59	      action: "prune",
 60	      globals: context?.suggestionGlobals,
 61	    }),
 62	  });
 63	}
