 65	export async function renderCommand(
 66	  rawArgs: string[],
 67	  context?: TasksContext,
 68	): Promise<string> {
 69	  const { store } = requireCtx(context);
 70	  const args = [...rawArgs];
 71	  const json = takeBoolFlag(args, "--json");
 72	  requirePositionals(args, 0, 0, RENDER_HELP.split("\n")[0]);
 73	  if (!store.render) {
 74	    throw unsupported("render", store.capabilities().backend);
 75	  }
