489	export async function updateCommand(
490	  rawArgs: string[],
491	  context?: TasksContext,
492	): Promise<string> {
493	  const { store } = requireCtx(context);
494	  const args = [...rawArgs];
495	
496	  const json = takeBoolFlag(args, "--json");
497	  const title = takeFlag(args, "--title");
498	  const body = takeBody(args);
499	  const archiveBody = takeBoolFlag(args, "--archive-body");
500	  const repo = requireNonEmptySingleLineFlagValue(
501	    "--repo",
502	    takeFlag(args, "--repo"),
503	  );
504	  const kind = requireNonEmptySingleLineFlagValue(
505	    "--kind",
506	    takeFlag(args, "--kind"),
507	  );
508	  const priority = parsePriority(takeFlag(args, "--priority"));
509	  const pr = takeFlag(args, "--pr");
510	  const report = takeFlag(args, "--report");
511	  const positionals = requirePositionals(
512	    args,
513	    1,
514	    1,
515	    UPDATE_HELP.split("\n")[0],
516	  );
517	  const id = requireId(positionals[0], "id");
518	
519	  const patch: TaskPatch = {};
520	  if (title !== undefined) {
521	    patch.title = requireTitle(
522	      title,
523	      "--title must not be empty",
524	      'Pass a non-empty title, e.g. --title "new title"',
525	    );
526	  }
527	  if (body !== undefined) {
528	    patch.body = requireNonEmptyFlagValue("--body", body);
529	    if (archiveBody) patch.archiveBody = true;
530	  }
531	  if (archiveBody && body === undefined) {
532	    throw new AxiError(
533	      "--archive-body requires --body or --body-file",
534	      "VALIDATION_ERROR",
535	      [
536	        "Inspect the current task first, then pass a replacement body with --body or --body-file",
537	      ],
538	    );
539	  }
540	  if (repo !== undefined) {
541	    patch.repo = repo;
542	  }
543	  if (kind !== undefined) {
544	    patch.kind = kind;
545	  }
546	  if (priority !== undefined) patch.priority = priority;
547	  const addLinks = parseLinks(pr, report);
548	  if (addLinks.length > 0) patch.addLinks = addLinks;
549	
550	  if (Object.keys(patch).length === 0) {
551	    throw new AxiError("Nothing to update", "VALIDATION_ERROR", [
552	      "Pass a field, e.g. --title, --body, --body-file, --repo, or --kind",
553	    ]);
554	  }
555	
556	  if (!(await store.get(id))) {
557	    throw notFound(id, { globals: context?.suggestionGlobals });
558	  }
559	  const result = await store.update(id, patch);
560	  const task = result.task;
561	  const changed = orderUpdateChanges(result.changed);
562	  const already = changed.length === 0;
563	  const all = (await store.list({})).items;
564	  return renderMutation({
565	    json,
566	    confirm: already
567	      ? `updated ${id} already`
568	      : `updated ${id} (${changed.join(", ")})`,
569	    already,
570	    jsonPayload: {
571	      ok: true,
572	      action: "update",
573	      ...(already ? { already: true } : {}),
574	      changed,
575	      task: taskToJson(task, all),
840	    ![
841	      "ready",
842	      "preflight-matched",
843	      "delivery-registered",
844	      "retry-due",
845	    ].includes(current.state)
846	  ) {
847	    throw new AxiError(
848	      `Cannot begin delivery from state ${current.state}`,
849	      "VALIDATION_ERROR",
850	    );
851	  }
852	  const next = nextPayload(task);
853	  next.delivery.payload_digest = hash;
854	  next.delivery.attempt_count += 1;
855	  next.delivery.state = "delivery-posting";
856	  next.delivery.last_error_code = null;
857	  next.delivery.next_attempt_at = null;
858	  next.delivery.last_error = null;
859	  const updated = await persistPublicFollowup(store, task, next, {
860	    requireUnblocked: true,
861	  });
862	  return publicMutationOutput({
863	    json,
864	    action: "begin-delivery",
865	    task: updated,
866	    all: (await store.list({})).items,
867	    changed: ["delivery"],
868	    context,
869	  });
870	}
