881	  const { store, config } = requireCtx(context);
882	  const args = [...rawArgs];
883	  const json = takeBoolFlag(args, "--json");
884	  const receipt = parsePostedReceipt(readJsonFile(args, "--receipt-file"));
885	  const positionals = requirePositionals(
886	    args,
887	    1,
888	    1,
889	    SUBCOMMAND_HELP["record-delivery"],
890	  );

